function formatSpec(format) {
  const map = {
    feed_3x4: { size: '1024x1536', aspect_ratio: '3:4', objective: 'feed equilibrado e comercial' },
    stories_9x16: { size: '1024x1792', aspect_ratio: '9:16', objective: 'leitura imediata para stories/reels' },
